/* From Uiverse.io by elijahgummer  - Tags: simple, animation, green, switch, modern, transition */
.__UIV_SCOPE__ .inp {
  appearance: none;
}

.__UIV_SCOPE__ .check {
  position: relative;
  display: inline-block;
  width: 40px;
  height: 20px;
  background: #111;
  border-radius: 40px;
}

.__UIV_SCOPE__ .check:before {
  content: "";
  position: absolute;
  top: 8px;
  left: 4px;
  width: 3px;
  height: 3px;
  border-radius: 90px;
  transition: transform 0.5s;
  box-shadow: 7.9px 0 0 5px #14f960; /* Change the color here */
}

.__UIV_SCOPE__ .inp:checked ~ .check:before {
  transform: translateX(13px);
}

.__UIV_SCOPE__ .check:after {
  content: "N";
  position: absolute;
  right: -16px;
  top: -5px;
  font-size: 20px;
  color: #111;
  opacity: 0;
  transition: opacity 0.5s, transform 0.5s;
  transform: translateX(20px);
}

.__UIV_SCOPE__ .inp:checked ~ .check:after {
  opacity: 1;
  transform: translateX(0px);
}
